-- Heat Check: Lv3 (Hot) cards, served only by the server.
-- Generated by tools/cards.mjs --seed from content/*.json. Do not edit by hand.
-- Run after both migrations. Safe to re-run: existing cards are kept.

on conflict (game, text) do update set is_taste = excluded.is_taste, extra = excluded.extra, optional_dare = excluded.optional_dare;
